/* eslint-disable */

import { readFileSync } from 'node:fs'

// Read on first use: package.json is generated by the build, so loading the plugin must not depend on it.
let keys

const getKeys = () => keys ??= Object.keys(JSON.parse(readFileSync(new URL('../../package.json', import.meta.url), 'utf8')).exports)

export default {
  meta: {
    type: "suggestion",
    docs: {
      description: 'Restrict specific imports and provide replacement',
      category: 'Best Practices',
      recommended: true,
    },
    fixable: 'code',
  },

  create: function (context) {
    return {
      ImportDeclaration(node) {
        const source = node.source.value
        const importSpecifiers = node.specifiers.filter(specifier => specifier.type === 'ImportSpecifier')

        importSpecifiers.forEach(specifier => {
          if (!source.includes('eco-vue-js')) return

          const importedName = specifier.imported.name

          if (importedName.startsWith('W')) {
            const path = getKeys().find(item => item.includes(importedName))

            if (!path) return

            const replacementImport = `import ${ importedName } from 'eco-vue-js${ path.substring(1) }'`

            context.report({
              node,
              message: `Do not import '${ importedName }' directly. Use the replacement: ${ replacementImport }`,
              fix: function (fixer) {
                return fixer.replaceText(node, replacementImport)
              },
            })

            return
          }

          if (source.includes('iconsSax')) {
            const replacementImport = `import ${ importedName } from 'eco-vue-js/dist/assets/icons/${ importedName }'`
            context.report({
              node,
              message: `Do not import '${ importedName }' directly. Use the replacement: ${ replacementImport }`,
              fix: function (fixer) {
                return fixer.replaceText(node, replacementImport)
              },
            })

            return
          }

          if (source.includes('iconsDefault')) {
            const replacementImport = `import ${ importedName } from 'eco-vue-js/dist/assets/icons/${ importedName }'`
            context.report({
              node,
              message: `Do not import '${ importedName }' directly. Use the replacement: ${ replacementImport }`,
              fix: function (fixer) {
                return fixer.replaceText(node, replacementImport)
              },
            })

            return
          }
        })
      },
    }
  },
}